class Solution {
public:
    int alternatingSubarray(vector<int>& nums) {
        int n = nums.size();
        int ans = -1;
        for (int i = 0; i < n; ++i) {
            int diff = 1;
            int j = i;
            while (j + 1 < n && nums[j + 1] - nums[j] == diff) {
                diff *= -1;
                j++;
            }
            if (j > i) ans = max(ans, j - i + 1);
        }
        return ans;
    }
};

class Solution {
    public int alternatingSubarray(int[] nums) {
        int n = nums.length;
        int ans = -1;
        for (int i = 0; i < n; i++) {
            int diff = 1;
            int j = i;
            while (j + 1 < n && nums[j + 1] - nums[j] == diff) {
                diff *= -1;
                j++;
            }
            if (j > i) ans = Math.max(ans, j - i + 1);
        }
        return ans;
    }
}

var alternatingSubarray = function(nums) {
    const n = nums.length;
    let ans = -1;
    for (let i = 0; i < n; i++) {
        let diff = 1;
